"""CasADi model of a building generated by Trano with the ``FastSmoothBuildingsMPC`` library.

``FastSmoothBuildingsMPC`` turns the YAML description of a building into a model close to the Buildings library (layered
walls, windows with their angular optics, hydronic circuits, boilers, heat pumps, ventilation, PV) that rumoca
translates into an explicit ODE ``xdot = f(t, x, u, p)``:

* the roles of the variables are read from the Modelica model itself (:class:`trano_optimization.Roles`): an input
  with a ``min`` and a ``max`` is a **control** (valve positions, boiler part load ratio, heat pump speed, all
  between 0 and 1, or the heat of an ideal emitter in W), any other input a **disturbance** (the weather channels
  and the internal gains per floor area); the ``TAir`` states are the comfort temperatures and the states in kWh
  are the energy **meters** of the systems;
* the model depends on the time: the solar position is computed inside it from the seconds of the year;
* it is nonlinear and stiff (water nodes): it is simulated with CVODES and optimised on Radau collocation points
  (:class:`trano_optimization.collocation.Collocated`);
* its variables are named after the elements of the YAML (``space_001.TAir``, ``boiler_001.EEle``): the model is
  generated without the containers of Trano (``envelope1``, ``production1``, ...), whose prefixes are stripped from
  the names of a containerised model read from a file (:func:`without_containers`).

The ``BuildingModel`` library of Trano gives the closed loop of the same building, with the controllers of its YAML:
the rule-based reference of the MPC (:func:`mpctrano.simulation.run_rule_based`).

The CasADi export of these models needs rumoca 0.10.3 (rumoca main up to ``c74cddf``), which ``uv sync`` builds.
"""

from __future__ import annotations

import fnmatch
import re
from collections import Counter
from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass, field, replace
from functools import cache, cached_property
from pathlib import Path
from typing import TYPE_CHECKING, get_args

import numpy as np
from trano_optimization import CasadiModel, CollocationSettings, Roles, Variable
from trano_optimization.collocation import Collocated

from mpctrano.forecast import OccupancySchedule
from mpctrano.units import STATE_BOUNDS

if TYPE_CHECKING:
    import pandas as pd
    from trano.topology import Network

MPC_LIBRARY = "FastSmoothBuildingsMPC"
CLOSED_LOOP_LIBRARY = "FastSmoothBuildings"
COMFORT_SUFFIX = ".TAir"
_TEMPERATURE_STATE = re.compile(r"\.T(\[\d+\])?$")
_WEATHER_FILE = re.compile(r"ReaderTMY3\s+\w+\s*\(\s*filNam\s*=[^\"]*\"([^\"]+)\"")
RUMOCA_COMMIT = "c74cddf"
"""Last rumoca commit known to export the connected FastSmoothBuildings models (later ones stop at residual
equations)."""

_PROBE = """package Probe
  connector Port Real T; flow Real Q_flow; end Port;
  model Node parameter Real C = 1; Real T(start = 290, fixed = true); Port port;
  equation port.T = T; C*der(T) = port.Q_flow; end Node;
  model Link Port a; Port b; equation a.Q_flow = a.T - b.T; a.Q_flow + b.Q_flow = 0; end Link;
  model M Node n1; Node n2; Link l; equation connect(n1.port, l.a); connect(l.b, n2.port); end M;
end Probe;
"""


class ModelError(ValueError):
    """The model, its inputs or its parameters are inconsistent."""


def _package_name(stem: str) -> str:
    sanitized = "".join(character if character.isalnum() or character == "_" else "_" for character in stem)
    return sanitized if sanitized[:1].isalpha() else f"m_{sanitized}"


def used_libraries(source: str, roots: Sequence[Path | str] = ()) -> list[Path]:
    """The folders of the libraries the Modelica ``source`` uses without holding them and ``roots`` lacks: the
    FastSmoothBuildings package installed with trano, as trano generates its models (``uses(FastSmoothBuildings(...))``
    without a copy of the library)."""
    import fastsmoothbuildings

    named = {Path(root).resolve() for root in roots}
    held = re.search(r"^\s*package FastSmoothBuildings\b", source, re.MULTILINE)
    if held or not re.search(r"\buses\s*\((?:[^;]*?\b)?FastSmoothBuildings\s*\(", source):
        return []
    library = Path(fastsmoothbuildings.LIBRARY)
    return [] if library.resolve() in named else [library]


@cache
def rumoca_exports_building_models() -> bool:
    """Whether the installed rumoca exports models made of connected components to CasADi."""
    import rumoca

    try:
        rumoca.Session().loads(_PROBE, model="Probe.M").to_casadi()
    except Exception:
        return False
    return True


@dataclass
class BuildingModel:
    """A Trano ``FastSmoothBuildingsMPC`` building model as CasADi functions.

    Build it from the YAML description (:meth:`from_yaml`, which calls Trano), from a Trano network
    (:meth:`from_network`) or from the Modelica package written by ``trano create-model house.yaml
    FastSmoothBuildingsMPC`` (:meth:`from_file`). :attr:`parameters` holds the current (initial or calibrated) values.
    """

    model: CasadiModel
    roles: Roles
    source: str
    parameters: np.ndarray
    base_dir: Path | None = None
    occupancy: dict[str, OccupancySchedule] = field(default_factory=dict)
    """Schedule of each occupancy model (by name, the ``<name>_gai`` inputs), from the Trano network."""
    weather_file: str | None = None
    """Weather file of the runnable model, as written in it (a path or a ``modelica://`` URI)."""
    _collocated: dict[float, Collocated] = field(default_factory=dict, init=False, repr=False)

    # ----------------------------------------------------------------- constructors
    @classmethod
    def from_source(
        cls,
        source: str,
        model: str,
        roles: Roles | None = None,
        base_dir: Path | None = None,
        occupancy: Mapping[str, OccupancySchedule] | None = None,
        roots: Sequence[Path | str] = (),
    ) -> BuildingModel:
        """Translate ``model`` (``<package>.building_mpc``) of the Modelica ``source`` with rumoca.

        The weather file is read from the weather reader of the runnable model; the ``occupancy`` schedules (by
        occupancy model name) cannot be read from the source and default to no gains. ``roots`` are the folders of
        the libraries the source uses without holding them; the installed FastSmoothBuildings is added when the
        source declares it, as trano writes its packages (:func:`used_libraries`).
        """
        try:
            casadi_model = CasadiModel.from_modelica(source, model, roots=[*roots, *used_libraries(source, roots)])
        except Exception as error:
            if not rumoca_exports_building_models():
                raise ModelError(
                    f"The installed rumoca cannot export FastSmoothBuildings models to CasADi; install rumoca main at "
                    f"{RUMOCA_COMMIT} (uv sync installs it)."
                ) from error
            raise
        casadi_model = with_temperature_units(without_containers(casadi_model))
        roles = roles or Roles.infer(casadi_model.description)
        roles.check(casadi_model.description)
        return cls(
            model=casadi_model,
            roles=roles,
            source=source,
            parameters=casadi_model.description.parameter_values,
            base_dir=base_dir,
            occupancy=dict(occupancy or {}),
            weather_file=match.group(1) if (match := _WEATHER_FILE.search(source)) else None,
        )

    @classmethod
    def from_file(
        cls,
        modelica: Path | str,
        model: str | None = None,
        roles: Roles | None = None,
        occupancy: Mapping[str, OccupancySchedule] | None = None,
        roots: Sequence[Path | str] = (),
    ) -> BuildingModel:
        """Load ``house.mo``; ``model`` defaults to ``<stem>.building_mpc``.

        The package can be containerised (``trano create-model`` writes it so): the container prefixes are stripped.
        A package that uses FastSmoothBuildings without holding it (trano's default) reads it from the installed
        package; ``roots`` are the folders of the other libraries it uses.
        """
        path = Path(modelica)
        return cls.from_source(
            path.read_text(),
            model or f"{path.stem}.building_mpc",
            roles=roles,
            base_dir=path.parent,
            occupancy=occupancy,
            roots=roots,
        )

    @classmethod
    def from_network(cls, network: Network, roles: Roles | None = None, base_dir: Path | None = None) -> BuildingModel:
        """The model of a network generated with the ``FastSmoothBuildingsMPC`` library, with its occupancy schedules.

        The model is generated without containers, so its variables have the names of the elements of the network.
        """
        return cls.from_source(
            network.model(include_container=False),
            f"{network.name}.building_mpc",
            roles=roles,
            base_dir=base_dir,
            occupancy=network_occupancy(network),
            roots=network.libraries,
        )

    @classmethod
    def from_yaml(
        cls,
        path: Path | str,
        name: str | None = None,
        roles: Roles | None = None,
        library: str = MPC_LIBRARY,
        base_dir: Path | None = None,
    ) -> BuildingModel:
        """Generate the model with Trano from a building description.

        ``library`` is ``FastSmoothBuildingsMPC`` (the controls of the systems are inputs, for MPC) or
        ``FastSmoothBuildings`` (the closed loop with the controllers of the YAML: the baseline of
        :func:`mpctrano.simulation.run_rule_based`). The weather file is looked up in ``base_dir`` (the directory of
        the YAML by default).
        """
        from trano.data_models.conversion import convert_network
        from trano.elements.library.library import Library

        if library not in (MPC_LIBRARY, CLOSED_LOOP_LIBRARY):
            raise ValueError(f"library must be {MPC_LIBRARY!r} or {CLOSED_LOOP_LIBRARY!r}, not {library!r}.")
        path = Path(path).resolve()
        library_ = Library.from_configuration(library)
        network = convert_network(name or _package_name(path.stem), path, library=library_)
        return cls.from_network(network, roles=roles, base_dir=base_dir or path.parent)

    def write(self, directory: Path | str, stem: str | None = None) -> Path:
        """Write the Modelica package (``<stem>.mo``)."""
        directory = Path(directory)
        directory.mkdir(parents=True, exist_ok=True)
        path = directory / f"{stem or self.name.split('.')[0]}.mo"
        path.write_text(self.source)
        return path

    # ----------------------------------------------------------------- names and indices
    @property
    def name(self) -> str:
        return str(self.model.description.name)

    @property
    def state_names(self) -> list[str]:
        return list(self.model.description.state_names)

    @property
    def input_names(self) -> list[str]:
        return list(self.model.description.input_names)

    @property
    def parameter_names(self) -> list[str]:
        return list(self.model.description.parameter_names)

    @cached_property
    def control_names(self) -> list[str]:
        return list(self.roles.controls)

    @cached_property
    def disturbance_names(self) -> list[str]:
        return list(self.roles.disturbances)

    @cached_property
    def comfort_states(self) -> list[str]:
        """Air temperature state of each zone (the comfort variable)."""
        return list(self.roles.comfort)

    @cached_property
    def zone_names(self) -> list[str]:
        return [name.removesuffix(COMFORT_SUFFIX) for name in self.comfort_states]

    @cached_property
    def comfort_indices(self) -> list[int]:
        return [self.state_names.index(name) for name in self.comfort_states]

    @cached_property
    def meters(self) -> dict[str, str]:
        """Energy meter states [kWh] and their carrier (``electricity``, ``fuel``, ``electricity_production``)."""
        return dict(self.roles.meters)

    @cached_property
    def control_bounds(self) -> tuple[np.ndarray, np.ndarray]:
        """Lower and upper bounds of the controls, in their units."""
        variables = [self.model.description.input(name) for name in self.control_names]
        return (
            np.array([variable.minimum for variable in variables], dtype=float),
            np.array([variable.maximum for variable in variables], dtype=float),
        )

    @cached_property
    def heat_controls(self) -> list[str]:
        """Controls that are a heat flow in W (ideal emitters), bought at the electricity price."""
        return [name for name in self.control_names if self.model.description.input(name).unit == "W"]

    @property
    def n_states(self) -> int:
        return len(self.state_names)

    @property
    def n_controls(self) -> int:
        return len(self.control_names)

    @property
    def n_disturbances(self) -> int:
        return len(self.disturbance_names)

    @property
    def n_parameters(self) -> int:
        return len(self.parameter_names)

    @property
    def n_zones(self) -> int:
        return len(self.zone_names)

    @property
    def weather_path(self) -> Path | None:
        """The weather file of the runnable model on disk: its path, resolved against the directory of the model,
        or, for a ``modelica://`` resource, the file of the same name in that directory."""
        if self.weather_file is None:
            return None
        if self.weather_file.startswith("modelica://"):
            path = Path(self.weather_file.rsplit("/", 1)[-1])
        else:
            path = Path(self.weather_file)
        if not path.is_absolute() and self.base_dir is not None:
            path = self.base_dir / path
        return path.resolve() if path.exists() else None

    @property
    def initial_state(self) -> np.ndarray:
        return np.asarray(self.model.description.initial_state, dtype=float)

    # ----------------------------------------------------------------- parameters
    @property
    def parameter_values(self) -> dict[str, float]:
        return dict(zip(self.parameter_names, self.parameters.tolist(), strict=True))

    def parameter(self, name: str) -> float:
        return float(self.parameters[self.parameter_names.index(name)])

    def select_parameters(self, patterns: Iterable[str]) -> list[str]:
        """Parameter names matching any of the ``fnmatch`` patterns (e.g. ``"*.G"``, ``"space_001.*"``)."""
        patterns = list(patterns)
        return [name for name in self.parameter_names if any(fnmatch.fnmatch(name, pattern) for pattern in patterns)]

    def with_control_bounds(self, bounds: Mapping[str, tuple[float | None, float | None]]) -> BuildingModel:
        """Copy of the model with other bounds on some controls (``name: (lower, upper)``, ``None`` keeps a bound).

        The bounds of the model come from the Modelica ``min`` and ``max`` of its inputs; an ideal emitter
        (``Q_flow`` in W) is written with ``min=0``, heating only: a negative lower bound lets the controller cool
        with it (the equations hold, the emitter is a heat flow of either sign).
        """
        unknown = set(bounds) - set(self.control_names)
        if unknown:
            raise KeyError(f"Unknown controls: {sorted(unknown)}")
        inputs = []
        for original in self.model.description.inputs:
            variable = original
            if original.name in bounds:
                lower, upper = bounds[original.name]
                update = {"minimum": original.minimum if lower is None else float(lower)}
                update |= {"maximum": original.maximum if upper is None else float(upper)}
                variable = original.model_copy(update=update)
            inputs.append(variable)
        model = CasadiModel(
            rhs=self.model.rhs, description=self.model.description.model_copy(update={"inputs": tuple(inputs)})
        )
        return replace(self, model=model)

    def smooth_controllers(self, width_factor: float = 5.0, switching_time: float = 600.0) -> BuildingModel:
        """Copy of a closed-loop model with gentler controllers: every smooth transition of its controllers widened
        by ``width_factor`` and every hysteresis switching over ``switching_time`` [s].

        The controllers of Trano's FastSmoothBuildings reproduce switching controllers (thermostats, demand and buffer
        hysteresis, limiters) as steep smooth transitions and fast bistable states (trano >= 0.59: the parameters
        ``dU``, ``dY``, ``dMax``, ``dT``, ``dtSet`` and ``tau`` of ``FastSmoothBuildings.Controls``). CVODES follows
        them, but every switch that moves by a sample makes the calibration objective jumpy: the gentler copy is the
        model to calibrate. The defaults (five times wider, switching over ten minutes) keep its trajectory within 0.15
        K of the sharp model on the single-zone house and divide the time of a shooting calibration by ten without
        biasing it; wider transitions (x10 and beyond) smear the thermostat and bias the conductances low. A model
        without these parameters (an older trano, or no controller) is returned as it is.
        """
        widths = (".dU", ".dY", ".dMax", ".dT", ".dtSet")
        values: dict[str, float] = {}
        for name, value in zip(self.parameter_names, self.parameters, strict=True):
            if name.endswith(widths) and np.isfinite(value):
                values[name] = float(value) * width_factor
            elif name.endswith(".tau") and np.isfinite(value):
                values[name] = switching_time
        return self.with_parameters(values) if values else self

    def with_parameters(self, values: Mapping[str, float] | Sequence[float] | np.ndarray) -> BuildingModel:
        """Copy of the model with other parameter values (a mapping of names or a full vector)."""
        if isinstance(values, Mapping):
            unknown = set(values) - set(self.parameter_names)
            if unknown:
                raise KeyError(f"Unknown parameters: {sorted(unknown)}")
            vector = self.parameters.copy()
            for name, value in values.items():
                vector[self.parameter_names.index(name)] = float(value)
        else:
            vector = np.asarray(values, dtype=float).reshape(-1)
            if vector.size != self.n_parameters:
                raise ModelError(f"Expected {self.n_parameters} parameters, got {vector.size}.")
        return replace(self, parameters=vector)

    # ----------------------------------------------------------------- dynamics
    def collocation_settings(self, time_step: float, **settings: object) -> CollocationSettings:
        return CollocationSettings(time_step=time_step, temperature_bounds=STATE_BOUNDS, **settings)

    def collocated(self, time_step: float) -> Collocated:
        """The model collocated over steps of ``time_step`` [s], with a CVODES simulator (cached)."""
        if time_step not in self._collocated:
            self._collocated[time_step] = Collocated(
                self.model, self.roles, self.collocation_settings(time_step), self.parameters
            )
        return self._collocated[time_step]

    def simulate(
        self,
        x0: np.ndarray | Sequence[float],
        controls: np.ndarray,
        disturbances: np.ndarray,
        time_step: float,
        start_time: float = 0.0,
    ) -> np.ndarray:
        """Open-loop simulation (CVODES): ``(n_states, N + 1)`` trajectory for ``(n_controls, N)`` controls held
        over each step, from ``start_time`` [s of the year]."""
        controls = np.atleast_2d(np.asarray(controls, dtype=float))
        disturbances = np.atleast_2d(np.asarray(disturbances, dtype=float))
        steps = controls.shape[1]
        if disturbances.shape != (self.n_disturbances, steps) or controls.shape[0] != self.n_controls:
            raise ModelError(
                f"Expected controls ({self.n_controls}, N) and disturbances ({self.n_disturbances}, N), "
                f"got {controls.shape} and {disturbances.shape}."
            )
        states = self.collocated(time_step).simulate(np.asarray(x0, dtype=float), controls, disturbances, start_time)
        return np.asarray(states, dtype=float)

    def simulate_frame(self, x0: np.ndarray | Sequence[float], inputs: pd.DataFrame) -> pd.DataFrame:
        """:meth:`simulate` with a time-indexed frame of inputs; returns the states on the same index."""
        import pandas as pd

        from mpctrano.data import time_step_of
        from mpctrano.forecast import seconds_of_year

        index = pd.DatetimeIndex(inputs.index)
        controls = inputs[self.control_names].to_numpy(dtype=float).T[:, :-1]
        disturbances = inputs[self.disturbance_names].to_numpy(dtype=float).T[:, :-1]
        start = float(seconds_of_year(index[:1])[0])
        states = self.simulate(x0, controls, disturbances, time_step_of(index), start_time=start)
        return pd.DataFrame(states.T, index=index, columns=self.state_names)


def network_occupancy(network: Network) -> dict[str, OccupancySchedule]:
    """Schedule of each occupancy model of a network, by name."""
    from trano.elements import Space

    return {
        space.occupancy.name: OccupancySchedule.from_parameters(space.occupancy.processed_parameters(network.library))
        for space in network.graph.nodes
        if isinstance(space, Space) and space.occupancy is not None
    }


@cache
def _container_prefix() -> re.Pattern[str]:
    """Prefix of the variables of an element in a containerised model: ``<container type>1.`` (as Trano names the
    instances of its containers)."""
    from trano.elements.types import ContainerTypes

    return re.compile(rf"^(?:{'|'.join(get_args(ContainerTypes))})1\.")


def without_containers(model: CasadiModel) -> CasadiModel:
    """The model with the names of its elements: ``envelope1.space_001.TAir`` -> ``space_001.TAir``.

    Trano groups the elements of a model in containers (``envelope1``, ``emission1``, ``distribution1``,
    ``production1``, ...) unless it is generated with ``include_container=False``; the names of the states and
    parameters then start with the container. The CasADi function is positional: only the description changes.
    """
    prefix = _container_prefix()
    description = model.description

    def stripped(variables: tuple[Variable, ...]) -> tuple[Variable, ...]:
        return tuple(variable.model_copy(update={"name": prefix.sub("", variable.name)}) for variable in variables)

    states, inputs, parameters = (
        stripped(variables) for variables in (description.states, description.inputs, description.parameters)
    )
    if (states, inputs, parameters) == (description.states, description.inputs, description.parameters):
        return model
    for kind, variables in (("states", states), ("inputs", inputs), ("parameters", parameters)):
        if duplicates := sorted(name for name, count in Counter(v.name for v in variables).items() if count > 1):
            raise ModelError(f"The {kind} of {description.name} have the same names without containers: {duplicates}")
    return CasadiModel(
        rhs=model.rhs,
        description=description.model_copy(update={"states": states, "inputs": inputs, "parameters": parameters}),
    )


def with_temperature_units(model: CasadiModel) -> CasadiModel:
    """The model with the unit ``K`` restored on its temperature states that lost it.

    rumoca does not report the unit of array states (the layers ``T[i]`` of the walls, the water of the radiators);
    the collocation then leaves them in kelvin instead of shifting them to degrees Celsius, and the temperature
    bounds miss them. A state without a unit named ``...T`` or ``...T[i]`` and starting at a temperature in kelvin
    is a temperature.
    """
    low, high = STATE_BOUNDS
    states = tuple(
        variable.model_copy(update={"unit": "K"})
        if not variable.unit
        and _TEMPERATURE_STATE.search(variable.name)
        and variable.value is not None
        and low <= variable.value <= high
        else variable
        for variable in model.description.states
    )
    if states == model.description.states:
        return model
    return CasadiModel(rhs=model.rhs, description=model.description.model_copy(update={"states": states}))
